void AValopracPawn::ClearInput(){Input=valoprac::Input();AdsToggled=false;}
void AValopracPawn::FireDown(){if(!Paused){Input.fire=true;Input.presses=1;}}void AValopracPawn::FireUp(){Input.fire=false;}
void AValopracPawn::AdsDown(){if(Paused)return;if(AdsToggle)AdsToggled=!AdsToggled;Input.ads=AdsToggle?AdsToggled:true;}void AValopracPawn::AdsUp(){if(!AdsToggle)Input.ads=false;}
void AValopracPawn::Reload(){Input.reload=true;}void AValopracPawn::SelectOne(){Switch(0);}void AValopracPawn::SelectTwo(){Switch(1);}void AValopracPawn::SelectThree(){Switch(2);}void AValopracPawn::OpenMenu(){Paused=true;ClearInput();Send();}
