 double PreviousReload=W.reloadUntil;W.step(Time,Dt,Input,[this](){Fire();});if(PreviousReload<0&&W.reloadUntil>=0)Play(TEXT("reload"));for(int I=0;I<3;I++)if(I!=WeaponId){auto& Other=Weapons[I];Other.recoil.recover(Dt,Other.p,Time-Other.lastShot);Other.bloom=std::max(0.0,Other.bloom-Other.p.bloomRecovery*Dt);}
