void AValopracPawn::Play(const FString& Action){Voices.RemoveAll([](const auto& V){return !V.IsValid()||!V->IsPlaying();});if(Voices.Num()>=48){if(Voices[0].IsValid())Voices[0]->Stop();Voices.RemoveAt(0);}auto* Sound=Sounds.Find(FString(Ids[WeaponId])+TEXT("_")+Action);if(Sound&&*Sound){float Volume=float(MasterVolume*(Action==TEXT("fire")?FiringVolume:Action==TEXT("elimination")?FeedbackVolume:HandlingVolume));if(auto* Voice=UGameplayStatics::SpawnSound2D(this,*Sound,Volume))Voices.Add(Voice);}}
